{
  "id": 33,
  "knowledge": "Geographic Concentration Index (GCI)",
  "description": "Measures the geographic concentration of visa applications.",
  "definition": "GCI = sum((Applications in State i / Total Applications)^2) for all states. State and application information are included in the application data."
}

{
  "id": 19,
  "knowledge": "State Application Distribution (SAD)",
  "description": "Measures the percentage of applications in each state.",
  "definition": "SAD = (Number of Applications in State / Total Number of Applications) \u00d7 100%. State information is included in the worksite data."
}

{
  "id": 16,
  "knowledge": "Worksite Density (WD)",
  "description": "Measures the number of visa workers per worksite.",
  "definition": "WD = (Number of Workers at Worksite / Number of Worksites). Worksite and worker information are recorded as part of the application data."
}

{
  "id": 15,
  "knowledge": "Employer H-1B Concentration (EHC)",
  "description": "Measures the proportion of H-1B applications submitted by an employer relative to all applications.",
  "definition": "EHC = (Number of H-1B Applications by Employer / Total Number of H-1B Applications) \u00d7 100%. Visa classification and employer information are tracked in the application data."
}
